#!/bin/bash\n\n# Enhanced Cluster Testing Script with Health Checks and Failover\n# Tests distributed locks, WebSocket sticky sessions, health monitoring, and automatic failover\n\necho \"🚀 Starting Enhanced NewsAggregator Cluster Test\"\n\n# Colors for output\nRED='\\033[0;31m'\nGREEN='\\033[0;32m'\nYELLOW='\\033[1;33m'\nBLUE='\\033[0;34m'\nNC='\\033[0m' # No Color\n\n# Configuration\nADMIN_TOKEN=${ADMIN_TOKEN:-\"your-admin-token-here\"}\nBASE_URL=\"http://localhost\"\nNGINX_PORT=80\nNODE1_PORT=5001\nNODE2_PORT=5002\n\necho -e \"${YELLOW}Configuration:${NC}\"\necho \"  Admin Token: $ADMIN_TOKEN\"\necho \"  Base URL: $BASE_URL\"\necho \"  Nginx Port: $NGINX_PORT\"\necho \"  Node Ports: $NODE1_PORT, $NODE2_PORT\"\necho \"\"\n\n# Function to check if service is running\ncheck_service() {\n    local url=$1\n    local name=$2\n    \n    if curl -s \"$url/api/health\" > /dev/null; then\n        echo -e \"${GREEN}✓${NC} $name is running\"\n        return 0\n    else\n        echo -e \"${RED}✗${NC} $name is not responding\"\n        return 1\n    fi\n}\n\n# Function to test API endpoint\ntest_api() {\n    local url=$1\n    local description=$2\n    \n    echo -n \"Testing $description... \"\n    \n    response=$(curl -s -w \"%{http_code}\" \"$url\")\n    http_code=\"${response: -3}\"\n    \n    if [ \"$http_code\" = \"200\" ]; then\n        echo -e \"${GREEN}✓${NC}\"\n        return 0\n    else\n        echo -e \"${RED}✗ (HTTP $http_code)${NC}\"\n        return 1\n    fi\n}\n\n# Function to test admin API\ntest_admin_api() {\n    local url=$1\n    local description=$2\n    \n    echo -n \"Testing $description... \"\n    \n    response=$(curl -s -w \"%{http_code}\" -H \"Authorization: Bearer $ADMIN_TOKEN\" \"$url\")\n    http_code=\"${response: -3}\"\n    \n    if [ \"$http_code\" = \"200\" ]; then\n        echo -e \"${GREEN}✓${NC}\"\n        return 0\n    else\n        echo -e \"${RED}✗ (HTTP $http_code)${NC}\"\n        return 1\n    fi\n}\n\n# Function to get JSON field value\nget_json_field() {\n    local json=$1\n    local field=$2\n    echo \"$json\" | jq -r \".$field\" 2>/dev/null || echo \"null\"\n}\n\necho \"=== Phase 1: Service Health Checks ===\"\n\n# Check individual nodes\ncheck_service \"$BASE_URL:$NODE1_PORT\" \"Node 1\"\ncheck_service \"$BASE_URL:$NODE2_PORT\" \"Node 2\"\n\n# Check load balancer\ncheck_service \"$BASE_URL:$NGINX_PORT\" \"Load Balancer (Nginx)\"\n\necho \"\"\necho \"=== Phase 2: API Load Balancing Tests ===\"\n\n# Test public API through load balancer\ntest_api \"$BASE_URL:$NGINX_PORT/api/health\" \"Health endpoint via LB\"\ntest_api \"$BASE_URL:$NGINX_PORT/api/news/sources\" \"News sources via LB\"\n\n# Test admin API through load balancer\ntest_admin_api \"$BASE_URL:$NGINX_PORT/api/admin/cluster/health\" \"Cluster health via LB\"\ntest_admin_api \"$BASE_URL:$NGINX_PORT/api/admin/cluster/nodes\" \"Cluster nodes via LB\"\ntest_admin_api \"$BASE_URL:$NGINX_PORT/api/admin/cluster/websockets\" \"WebSocket stats via LB\"\n\necho \"\"\necho \"=== Phase 3: Health Monitoring Tests ===\"\n\n# Test detailed health endpoint\necho -n \"Testing detailed health monitoring... \"\nhealth_response=$(curl -s -H \"Authorization: Bearer $ADMIN_TOKEN\" \"$BASE_URL:$NGINX_PORT/api/admin/cluster/health-detailed\")\nhealth_code=$(curl -s -w \"%{http_code}\" -H \"Authorization: Bearer $ADMIN_TOKEN\" \"$BASE_URL:$NGINX_PORT/api/admin/cluster/health-detailed\")\nhealth_code=\"${health_code: -3}\"\n\nif [ \"$health_code\" = \"200\" ]; then\n    echo -e \"${GREEN}✓${NC}\"\n    \n    # Parse health data\n    total_nodes=$(get_json_field \"$health_response\" \"health.totalNodes\")\n    healthy_nodes=$(get_json_field \"$health_response\" \"health.healthyNodes\")\n    degraded_nodes=$(get_json_field \"$health_response\" \"health.degradedNodes\")\n    unhealthy_nodes=$(get_json_field \"$health_response\" \"health.unhealthyNodes\")\n    \n    echo \"  📊 Health Summary:\"\n    echo \"    Total Nodes: $total_nodes\"\n    echo \"    Healthy: $healthy_nodes\"\n    echo \"    Degraded: $degraded_nodes\"\n    echo \"    Unhealthy: $unhealthy_nodes\"\nelse\n    echo -e \"${RED}✗ (HTTP $health_code)${NC}\"\nfi\n\necho \"\"\necho \"=== Phase 4: Failover System Tests ===\"\n\n# Test failover status\necho -n \"Testing failover status... \"\nfailover_response=$(curl -s -H \"Authorization: Bearer $ADMIN_TOKEN\" \"$BASE_URL:$NGINX_PORT/api/admin/cluster/failover-status\")\nfailover_code=$(curl -s -w \"%{http_code}\" -H \"Authorization: Bearer $ADMIN_TOKEN\" \"$BASE_URL:$NGINX_PORT/api/admin/cluster/failover-status\")\nfailover_code=\"${failover_code: -3}\"\n\nif [ \"$failover_code\" = \"200\" ]; then\n    echo -e \"${GREEN}✓${NC}\"\n    \n    # Parse failover data\n    failover_enabled=$(get_json_field \"$failover_response\" \"failover.enabled\")\n    failover_in_progress=$(get_json_field \"$failover_response\" \"failover.inProgress\")\n    failover_count=$(get_json_field \"$failover_response\" \"failover.failoverCount\")\n    max_failovers=$(get_json_field \"$failover_response\" \"failover.policy.maxFailoversPerHour\")\n    \n    echo \"  🔄 Failover Status:\"\n    echo \"    Enabled: $failover_enabled\"\n    echo \"    In Progress: $failover_in_progress\"\n    echo \"    Count This Hour: $failover_count/$max_failovers\"\nelse\n    echo -e \"${RED}✗ (HTTP $failover_code)${NC}\"\nfi\n\n# Test failover history\ntest_admin_api \"$BASE_URL:$NGINX_PORT/api/admin/cluster/failover-history\" \"Failover history\"\n\necho \"\"\necho \"=== Phase 5: Distributed Lock Testing ===\"\n\necho -n \"Testing RSS collection locks... \"\n\n# Trigger manual collection on both nodes simultaneously\nresponse1=$(curl -s -w \"%{http_code}\" -X POST -H \"Authorization: Bearer $ADMIN_TOKEN\" \"$BASE_URL:$NODE1_PORT/api/admin/news/collect\")\nresponse2=$(curl -s -w \"%{http_code}\" -X POST -H \"Authorization: Bearer $ADMIN_TOKEN\" \"$BASE_URL:$NODE2_PORT/api/admin/news/collect\")\n\nhttp_code1=\"${response1: -3}\"\nhttp_code2=\"${response2: -3}\"\n\nif [ \"$http_code1\" = \"200\" ] && [ \"$http_code2\" = \"200\" ]; then\n    echo -e \"${GREEN}✓${NC} (Both nodes responded - distributed locking working)\"\nelse\n    echo -e \"${RED}✗ (Node1: $http_code1, Node2: $http_code2)${NC}\"\nfi\n\necho \"\"\necho \"=== Phase 6: WebSocket Cluster Tests ===\"\n\n# Test WebSocket connections (sticky sessions)\nif command -v wscat &> /dev/null; then\n    echo -n \"Testing WebSocket sticky sessions... \"\n    \n    # Test multiple connections to ensure they stick to nodes\n    timeout 3s wscat -c \"ws://$BASE_URL:$NGINX_PORT/ws\" -x '{\"type\":\"ping\"}' > /tmp/ws_test1.log 2>&1 &\n    timeout 3s wscat -c \"ws://$BASE_URL:$NGINX_PORT/ws\" -x '{\"type\":\"ping\"}' > /tmp/ws_test2.log 2>&1 &\n    \n    wait\n    \n    if [ -f /tmp/ws_test1.log ] && [ -f /tmp/ws_test2.log ]; then\n        echo -e \"${GREEN}✓${NC}\"\n    else\n        echo -e \"${RED}✗${NC}\"\n    fi\n    \n    rm -f /tmp/ws_test1.log /tmp/ws_test2.log\nelse\n    echo -e \"${YELLOW}⚠ WebSocket test skipped (wscat not available)${NC}\"\nfi\n\necho \"\"\necho \"=== Phase 7: Stress Testing (Optional) ===\"\n\nif command -v ab &> /dev/null; then\n    echo \"Running load test to trigger health monitoring...\"\n    ab -n 200 -c 20 \"$BASE_URL:$NGINX_PORT/api/health\" | grep -E \"(Requests per second|Time per request|Failed requests)\"\n    \n    echo \"\"\n    echo \"Waiting 10 seconds for health checks to process...\"\n    sleep 10\n    \n    # Check if health status changed\n    echo -n \"Checking post-load health status... \"\n    post_load_health=$(curl -s -H \"Authorization: Bearer $ADMIN_TOKEN\" \"$BASE_URL:$NGINX_PORT/api/admin/cluster/health-detailed\")\n    post_load_code=$(curl -s -w \"%{http_code}\" -H \"Authorization: Bearer $ADMIN_TOKEN\" \"$BASE_URL:$NGINX_PORT/api/admin/cluster/health-detailed\")\n    post_load_code=\"${post_load_code: -3}\"\n    \n    if [ \"$post_load_code\" = \"200\" ]; then\n        echo -e \"${GREEN}✓${NC}\"\n        \n        post_healthy=$(get_json_field \"$post_load_health\" \"health.healthyNodes\")\n        post_degraded=$(get_json_field \"$post_load_health\" \"health.degradedNodes\")\n        \n        echo \"  📊 Post-Load Health:\"\n        echo \"    Healthy: $post_healthy\"\n        echo \"    Degraded: $post_degraded\"\n    else\n        echo -e \"${RED}✗${NC}\"\n    fi\nelse\n    echo -e \"${YELLOW}⚠ Load testing skipped (Apache Bench not available)${NC}\"\nfi\n\necho \"\"\necho \"=== Phase 8: Manual Failover Test (Optional) ===\"\n\nread -p \"Do you want to test manual failover? (y/N): \" -n 1 -r\necho\nif [[ $REPLY =~ ^[Yy]$ ]]; then\n    # Get first available node for failover test\n    if [ \"$total_nodes\" -gt 1 ]; then\n        # Extract first node ID from health response\n        first_node=$(echo \"$health_response\" | jq -r '.health.nodes[0].nodeId' 2>/dev/null)\n        \n        if [ \"$first_node\" != \"null\" ] && [ \"$first_node\" != \"\" ]; then\n            echo \"Testing manual failover for node: $first_node\"\n            \n            failover_test=$(curl -s -X POST -H \"Authorization: Bearer $ADMIN_TOKEN\" \\\n                -H \"Content-Type: application/json\" \\\n                -d \"{\\\"nodeId\\\": \\\"$first_node\\\", \\\"reason\\\": \\\"Manual test failover\\\"}\" \\\n                \"$BASE_URL:$NGINX_PORT/api/admin/cluster/failover\")\n            \n            failover_test_code=$(curl -s -w \"%{http_code}\" -X POST -H \"Authorization: Bearer $ADMIN_TOKEN\" \\\n                -H \"Content-Type: application/json\" \\\n                -d \"{\\\"nodeId\\\": \\\"$first_node\\\", \\\"reason\\\": \\\"Manual test failover\\\"}\" \\\n                \"$BASE_URL:$NGINX_PORT/api/admin/cluster/failover\")\n            failover_test_code=\"${failover_test_code: -3}\"\n            \n            if [ \"$failover_test_code\" = \"200\" ]; then\n                echo -e \"${GREEN}✓ Manual failover initiated successfully${NC}\"\n                \n                echo \"Waiting 15 seconds for failover to complete...\"\n                sleep 15\n                \n                # Check failover status again\n                post_failover=$(curl -s -H \"Authorization: Bearer $ADMIN_TOKEN\" \"$BASE_URL:$NGINX_PORT/api/admin/cluster/failover-status\")\n                new_count=$(get_json_field \"$post_failover\" \"failover.failoverCount\")\n                \n                echo \"Failover count after test: $new_count\"\n            else\n                echo -e \"${RED}✗ Manual failover failed (HTTP $failover_test_code)${NC}\"\n            fi\n        else\n            echo -e \"${YELLOW}⚠ No valid node ID found for failover test${NC}\"\n        fi\n    else\n        echo -e \"${YELLOW}⚠ Need at least 2 nodes for failover test${NC}\"\n    fi\nelse\n    echo \"Manual failover test skipped\"\nfi\n\necho \"\"\necho \"=== Final Cluster Statistics ===\"\n\n# Get final cluster health information\necho \"Fetching final cluster statistics...\"\nfinal_health=$(curl -s -H \"Authorization: Bearer $ADMIN_TOKEN\" \"$BASE_URL:$NGINX_PORT/api/admin/cluster/health-detailed\")\nfinal_ws_stats=$(curl -s -H \"Authorization: Bearer $ADMIN_TOKEN\" \"$BASE_URL:$NGINX_PORT/api/admin/cluster/websockets\")\nfinal_failover=$(curl -s -H \"Authorization: Bearer $ADMIN_TOKEN\" \"$BASE_URL:$NGINX_PORT/api/admin/cluster/failover-status\")\n\nif [ $? -eq 0 ]; then\n    echo \"\"\n    echo \"📊 Final Health Summary:\"\n    echo \"$final_health\" | jq '.health | {totalNodes, healthyNodes, degradedNodes, unhealthyNodes}' 2>/dev/null || echo \"$final_health\"\n    \n    echo \"\"\n    echo \"🔌 WebSocket Summary:\"\n    echo \"$final_ws_stats\" | jq '.websockets | {totalNodes, totalConnections}' 2>/dev/null || echo \"$final_ws_stats\"\n    \n    echo \"\"\n    echo \"🔄 Failover Summary:\"\n    echo \"$final_failover\" | jq '.failover | {enabled, failoverCount, policy: {maxFailoversPerHour, cooldownMinutes}}' 2>/dev/null || echo \"$final_failover\"\nelse\n    echo -e \"${RED}Failed to fetch final statistics${NC}\"\nfi\n\necho \"\"\necho -e \"${GREEN}🎉 Enhanced cluster testing completed!${NC}\"\necho \"\"\necho \"Next steps:\"\necho \"1. Check cluster logs: docker-compose logs -f app-node-1 app-node-2\"\necho \"2. Monitor Redis: redis-cli monitor\"\necho \"3. Check Nginx access logs: docker-compose logs nginx\"\necho \"4. Open cluster dashboard: $BASE_URL:$NGINX_PORT/admin/monitor\"\necho \"5. Review health metrics: $BASE_URL:$NGINX_PORT/api/admin/cluster/health-detailed\"\necho \"6. Monitor failover events: $BASE_URL:$NGINX_PORT/api/admin/cluster/failover-history\"\necho \"\"\necho \"🔍 Monitoring URLs:\"\necho \"  - Cluster Health: $BASE_URL:$NGINX_PORT/api/admin/cluster/health-detailed\"\necho \"  - Failover Status: $BASE_URL:$NGINX_PORT/api/admin/cluster/failover-status\"\necho \"  - WebSocket Stats: $BASE_URL:$NGINX_PORT/api/admin/cluster/websockets\"\necho \"  - Node Details: $BASE_URL:$NGINX_PORT/api/admin/cluster/nodes\"